mapper.update:
/* ChkptLinkMapper.enableChkptLinkPreempt */
UPDATE TB_SITE_LINK
   SET CHKPT_LINK_STATUS  = 'ACTIVE'
     , CHKPT_LINK_DTIME   = NOW()
     , CHKPT_LINK_USER_CD = #{actorUserCd}
     , UPDATE_NO          = #{actorUserCd}
     , UPDATE_DATE        = NOW()
 WHERE LINK_ID           = #{linkId}
   AND STATUS            = 'ACTIVE'
   AND CHKPT_LINK_STATUS = 'NONE'
   AND SRC_CMPNY_CD      = #{actorCmpnyCd}
   AND DST_SITE_CD IS NOT NULL

/* ChkptLinkMapper.disableChkptLinkPreempt */
UPDATE TB_SITE_LINK
   SET CHKPT_LINK_STATUS  = 'NONE'
     , CHKPT_LINK_DTIME   = NOW()
     , CHKPT_LINK_USER_CD = #{actorUserCd}
     , UPDATE_NO          = #{actorUserCd}
     , UPDATE_DATE        = NOW()
 WHERE LINK_ID           = #{linkId}
   AND STATUS            = 'ACTIVE'
   AND CHKPT_LINK_STATUS = 'ACTIVE'
   AND (SRC_CMPNY_CD = #{actorCmpnyCd} OR DST_CMPNY_CD = #{actorCmpnyCd})

/* ChkptLinkMapper.clearChkptLinkStatusBySystem */
UPDATE TB_SITE_LINK
   SET CHKPT_LINK_STATUS  = 'NONE'
     , CHKPT_LINK_DTIME   = NOW()
     , CHKPT_LINK_USER_CD = #{actionUserCd}
     , UPDATE_NO          = #{actionUserCd}
     , UPDATE_DATE        = NOW()
 WHERE LINK_ID           = #{linkId}
   AND CHKPT_LINK_STATUS = 'ACTIVE'

mapper.select:
/* ChkptLinkMapper.selectMirrorChkptCd */
SELECT A.CHKPT_CD
FROM TB_CHKPT_TYPE_MGMT A
WHERE A.CMPNY_CD          = #{dstCmpnyCd}
  AND A.SITE_CD           = #{dstSiteCd}
  AND A.LINK_SRC_CMPNY_CD = #{srcCmpnyCd}
  AND A.LINK_SRC_SITE_CD  = #{srcSiteCd}
  AND A.LINK_SRC_CHKPT_CD = #{srcChkptCd}
LIMIT 1

/* ChkptLinkMapper.selectMirrorInspectItemCd */
SELECT A.INSPECT_ITEM_CD
FROM TB_CHKPT_INSPECT_ITEM A
WHERE A.CMPNY_CD          = #{dstCmpnyCd}
  AND A.SITE_CD           = #{dstSiteCd}
  AND A.LINK_SRC_CMPNY_CD = #{srcCmpnyCd}
  AND A.LINK_SRC_SITE_CD  = #{srcSiteCd}
  AND A.LINK_SRC_ITEM_CD  = #{srcItemCd}
LIMIT 1

/* ChkptLinkMapper.selectOrphanMirrorChkptCd */
SELECT A.CHKPT_CD
FROM TB_CHKPT_TYPE_MGMT A
WHERE A.CMPNY_CD               = #{dstCmpnyCd}
  AND A.SITE_CD                = #{dstSiteCd}
  AND A.LINK_SRC_CMPNY_CD IS NULL
  AND A.PREV_LINK_SRC_CMPNY_CD = #{srcCmpnyCd}
  AND A.PREV_LINK_SRC_SITE_CD  = #{srcSiteCd}
  AND A.PREV_LINK_SRC_CHKPT_CD = #{srcChkptCd}
ORDER BY A.CHKPT_CD
LIMIT 1

/* ChkptLinkMapper.selectOrphanMirrorInspectItemCd */
SELECT A.INSPECT_ITEM_CD
FROM TB_CHKPT_INSPECT_ITEM A
WHERE A.CMPNY_CD               = #{dstCmpnyCd}
  AND A.SITE_CD                = #{dstSiteCd}
  AND A.LINK_SRC_CMPNY_CD IS NULL
  AND A.PREV_LINK_SRC_CMPNY_CD = #{srcCmpnyCd}
  AND A.PREV_LINK_SRC_SITE_CD  = #{srcSiteCd}
  AND A.PREV_LINK_SRC_ITEM_CD  = #{srcItemCd}
ORDER BY A.INSPECT_ITEM_CD
LIMIT 1

mapper.update:
/* ChkptLinkMapper.reattachMirrorChkpt */
UPDATE TB_CHKPT_TYPE_MGMT
   SET LINK_SRC_CMPNY_CD      = PREV_LINK_SRC_CMPNY_CD
     , LINK_SRC_SITE_CD       = PREV_LINK_SRC_SITE_CD
     , LINK_SRC_CHKPT_CD      = PREV_LINK_SRC_CHKPT_CD
     , PREV_LINK_SRC_CMPNY_CD = NULL
     , PREV_LINK_SRC_SITE_CD  = NULL
     , PREV_LINK_SRC_CHKPT_CD = NULL
     , UPDATE_NO              = 'SYSTEM'
     , UPDATE_DATE            = NOW()
 WHERE CMPNY_CD               = #{dstCmpnyCd}
   AND SITE_CD                = #{dstSiteCd}
   AND CHKPT_CD               = #{dstChkptCd}
   AND LINK_SRC_CMPNY_CD IS NULL
   AND PREV_LINK_SRC_CMPNY_CD = #{srcCmpnyCd}
   AND PREV_LINK_SRC_SITE_CD  = #{srcSiteCd}
   AND PREV_LINK_SRC_CHKPT_CD = #{srcChkptCd}

/* ChkptLinkMapper.reattachMirrorInspectItem */
UPDATE TB_CHKPT_INSPECT_ITEM
   SET LINK_SRC_CMPNY_CD      = PREV_LINK_SRC_CMPNY_CD
     , LINK_SRC_SITE_CD       = PREV_LINK_SRC_SITE_CD
     , LINK_SRC_ITEM_CD       = PREV_LINK_SRC_ITEM_CD
     , PREV_LINK_SRC_CMPNY_CD = NULL
     , PREV_LINK_SRC_SITE_CD  = NULL
     , PREV_LINK_SRC_ITEM_CD  = NULL
     , UPDATE_NO              = 'SYSTEM'
     , UPDATE_DATE            = NOW()
 WHERE CMPNY_CD               = #{dstCmpnyCd}
   AND SITE_CD                = #{dstSiteCd}
   AND INSPECT_ITEM_CD        = #{dstItemCd}
   AND LINK_SRC_CMPNY_CD IS NULL
   AND PREV_LINK_SRC_CMPNY_CD = #{srcCmpnyCd}
   AND PREV_LINK_SRC_SITE_CD  = #{srcSiteCd}
   AND PREV_LINK_SRC_ITEM_CD  = #{srcItemCd}

mapper.select:
/* ChkptLinkMapper.selectInspectItemChkLstType */
SELECT A.CHKLST_TYPE
FROM TB_CHKPT_INSPECT_ITEM A
WHERE A.CMPNY_CD        = #{cmpnyCd}
  AND A.SITE_CD         = #{siteCd}
  AND A.INSPECT_ITEM_CD = #{itemCd}
LIMIT 1

mapper.update:
/* ChkptLinkMapper.propagateMirrorChkpt */
UPDATE TB_CHKPT_TYPE_MGMT D
    INNER JOIN TB_CHKPT_TYPE_MGMT S
        ON (
            S.CMPNY_CD = #{srcCmpnyCd}
        AND S.SITE_CD  = #{srcSiteCd}
        AND S.CHKPT_CD = #{srcChkptCd}
        AND S.CHKLST_TYPE = D.CHKLST_TYPE
        )
   SET D.CHKPT_NM     = S.CHKPT_NM
     , D.CHKPT_DESC   = S.CHKPT_DESC
     , D.USE_YN       = S.USE_YN
     , D.UPDATE_NO    = 'SYSTEM'
     , D.UPDATE_DATE  = NOW()
 WHERE D.CMPNY_CD          = #{dstCmpnyCd}
   AND D.SITE_CD           = #{dstSiteCd}
   AND D.CHKPT_CD          = #{dstChkptCd}
   AND D.LINK_SRC_CMPNY_CD = #{srcCmpnyCd}
   AND D.LINK_SRC_SITE_CD  = #{srcSiteCd}
   AND D.LINK_SRC_CHKPT_CD = #{srcChkptCd}

/* ChkptLinkMapper.propagateMirrorInspectItem */
UPDATE TB_CHKPT_INSPECT_ITEM D
    INNER JOIN TB_CHKPT_INSPECT_ITEM S
        ON (
            S.CMPNY_CD        = #{srcCmpnyCd}
        AND S.SITE_CD         = #{srcSiteCd}
        AND S.INSPECT_ITEM_CD = #{srcItemCd}
        AND S.CHKLST_TYPE     = D.CHKLST_TYPE
        )
   SET D.INSPECT_ITEM_SUBJ = S.INSPECT_ITEM_SUBJ
     , D.SORT_IDX          = S.SORT_IDX
     , D.STR_DATE          = CAST(
                                 GREATEST(
                                     CAST(S.STR_DATE AS UNSIGNED)
                                     , CAST(IFNULL(DATE_FORMAT(D.INSERT_DATE, '%Y%m%d'), '0') AS UNSIGNED)
                                 ) AS CHAR
                             )
     , D.USE_YN            = S.USE_YN
     , D.UPDATE_NO         = 'SYSTEM'
     , D.UPDATE_DATE       = NOW()
 WHERE D.CMPNY_CD          = #{dstCmpnyCd}
   AND D.SITE_CD           = #{dstSiteCd}
   AND D.INSPECT_ITEM_CD   = #{dstItemCd}
   AND D.LINK_SRC_CMPNY_CD = #{srcCmpnyCd}
   AND D.LINK_SRC_SITE_CD  = #{srcSiteCd}
   AND D.LINK_SRC_ITEM_CD  = #{srcItemCd}

/* ChkptLinkMapper.clearChkptLinkSrc */
UPDATE TB_CHKPT_TYPE_MGMT
   SET PREV_LINK_SRC_CMPNY_CD = LINK_SRC_CMPNY_CD
     , PREV_LINK_SRC_SITE_CD  = LINK_SRC_SITE_CD
     , PREV_LINK_SRC_CHKPT_CD = LINK_SRC_CHKPT_CD
     , LINK_SRC_CMPNY_CD      = NULL
     , LINK_SRC_SITE_CD       = NULL
     , LINK_SRC_CHKPT_CD      = NULL
     , UPDATE_NO              = #{updateNo}
     , UPDATE_DATE            = NOW()
 WHERE CMPNY_CD               = #{dstCmpnyCd}
   AND SITE_CD                = #{dstSiteCd}
   AND LINK_SRC_CMPNY_CD      = #{srcCmpnyCd}

/* ChkptLinkMapper.clearInspectItemLinkSrc */
UPDATE TB_CHKPT_INSPECT_ITEM
   SET PREV_LINK_SRC_CMPNY_CD = LINK_SRC_CMPNY_CD
     , PREV_LINK_SRC_SITE_CD  = LINK_SRC_SITE_CD
     , PREV_LINK_SRC_ITEM_CD  = LINK_SRC_ITEM_CD
     , LINK_SRC_CMPNY_CD      = NULL
     , LINK_SRC_SITE_CD       = NULL
     , LINK_SRC_ITEM_CD       = NULL
     , UPDATE_NO              = #{updateNo}
     , UPDATE_DATE            = NOW()
 WHERE CMPNY_CD               = #{dstCmpnyCd}
   AND SITE_CD                = #{dstSiteCd}
   AND LINK_SRC_CMPNY_CD      = #{srcCmpnyCd}

mapper.select:
/* ChkptLinkMapper.selectChkptChkLstType */
SELECT T.CHKLST_TYPE
FROM TB_CHKPT_TYPE_MGMT T
WHERE T.CMPNY_CD = #{cmpnyCd}
  AND T.SITE_CD  = #{siteCd}
  AND T.CHKPT_CD = #{chkptCd}
LIMIT 1

/* ChkptLinkMapper.selectChkptChildTiers */
SELECT
    T.CMPNY_CD              AS cmpnyCd
    , T.SITE_CD             AS siteCd
    , T.CHKLST_TYPE         AS chkLstType
    , T.CHKPT_CD            AS chkptCd
FROM TB_CHKPT_TYPE_MGMT T
WHERE T.LINK_SRC_CMPNY_CD = #{cmpnyCd}
  AND T.LINK_SRC_SITE_CD  = #{siteCd}
  AND T.LINK_SRC_CHKPT_CD = #{chkptCd}
ORDER BY T.CMPNY_CD, T.SITE_CD, T.CHKPT_CD

/* ChkptLinkMapper.selectItemLinkPairs */
SELECT
    I.INSPECT_ITEM_CD       AS itemCd
    , I.LINK_SRC_ITEM_CD    AS srcItemCd
FROM TB_CHKPT_INSPECT_ITEM I
WHERE I.CMPNY_CD          = #{dstCmpnyCd}
  AND I.SITE_CD           = #{dstSiteCd}
  AND I.CHKLST_TYPE       = #{chkLstType}
  AND I.LINK_SRC_CMPNY_CD = #{srcCmpnyCd}
  AND I.LINK_SRC_SITE_CD  = #{srcSiteCd}
  AND I.LINK_SRC_ITEM_CD IS NOT NULL
ORDER BY I.INSPECT_ITEM_CD

mapper.insert:
/* ChkptLinkMapper.upsertAnswer */
INSERT INTO TB_CHKPT_INSPECT_ANSWER (
      CMPNY_CD
    , SITE_CD
    , CHKPT_CD
    , INSPECT_ITEM_CD
    , WORK_DATE
    , INSPECT_ANSWER_TYPE
    , ANSWER_DESC
    , FILE_MGMT_CD
    , PERFORM_CMPNY_CD
    , PERFORM_USER_CD
    , PERFORM_USER_NM
    , INSERT_NO
    , INSERT_DATE
    , UPDATE_NO
    , UPDATE_DATE
) VALUES (
      #{cmpnyCd}
    , #{siteCd}
    , #{chkptCd}
    , #{inspectItemCd}
    , #{workDate}
    , #{inspectAnswerType}
    , #{answerDesc}
    , #{fileMgmtCd}
    , #{performCmpnyCd}
    , #{performUserCd}
    , #{performUserNm}
    , 'SYSTEM'
    , NOW()
    , 'SYSTEM'
    , NOW()
) AS NEW
ON DUPLICATE KEY UPDATE
      INSPECT_ANSWER_TYPE = NEW.INSPECT_ANSWER_TYPE
    , ANSWER_DESC         = NEW.ANSWER_DESC
    , FILE_MGMT_CD        = NEW.FILE_MGMT_CD
    , PERFORM_CMPNY_CD    = NEW.PERFORM_CMPNY_CD
    , PERFORM_USER_CD     = NEW.PERFORM_USER_CD
    , PERFORM_USER_NM     = NEW.PERFORM_USER_NM
    , UPDATE_NO           = 'SYSTEM'
    , UPDATE_DATE         = NOW()

/* ChkptLinkMapper.upsertDefectAction */
INSERT INTO TB_CHKPT_DEFECT_ACTION (
      CMPNY_CD
    , SITE_CD
    , CHKPT_CD
    , INSPECT_ITEM_CD
    , WORK_DATE
    , ACTION_DESC
    , FILE_MGMT_CD
    , ACTION_CMPNY_CD
    , ACTION_USER_CD
    , ACTION_USER_NM
    , INSERT_NO
    , INSERT_DATE
    , UPDATE_NO
    , UPDATE_DATE
) VALUES (
      #{cmpnyCd}
    , #{siteCd}
    , #{chkptCd}
    , #{inspectItemCd}
    , #{workDate}
    , #{actionDesc}
    , #{fileMgmtCd}
    , #{actionCmpnyCd}
    , #{actionUserCd}
    , #{actionUserNm}
    , 'SYSTEM'
    , NOW()
    , 'SYSTEM'
    , NOW()
) AS NEW
ON DUPLICATE KEY UPDATE
      ACTION_DESC     = NEW.ACTION_DESC
    , FILE_MGMT_CD    = NEW.FILE_MGMT_CD
    , ACTION_CMPNY_CD = NEW.ACTION_CMPNY_CD
    , ACTION_USER_CD  = NEW.ACTION_USER_CD
    , ACTION_USER_NM  = NEW.ACTION_USER_NM
    , UPDATE_NO       = 'SYSTEM'
    , UPDATE_DATE     = NOW()
